const IN_MIN = 0;      // Минимальное сырое число (обычно 0)
const IN_MAX = 65535;  // Максимальное сырое число (обычно 65535)

// 2. Выходной диапазон (Физические единицы датчика)
// Пример для температуры: от -50 до +150 градусов
// Пример для давления: от 0 до 10 бар
// Пример для тока: от -1000 до 1000 Ампер
const OUT_MIN = 40;     
const OUT_MAX = 2000;   

// ==========================================
// ⚙️ ЛОГИКА РАСЧЕТА
// ==========================================

// Получаем входящее значение (преобразуем в число на всякий случай)
let rawValue = Number(msg.payload);

// Формула линейной интерполяции:
// Y = [(X - Xmin) / (Xmax - Xmin)] * (Ymax - Ymin) + Ymin
let percent = (rawValue - IN_MIN) / (IN_MAX - IN_MIN);
let physicalValue = (percent * (OUT_MAX - OUT_MIN)) + OUT_MIN;

// 🛡️ Ограничитель (Clamping):
// Если значение вылезло за пределы (из-за помех или ошибок), 
// обрезаем его, чтобы не показать 105% или -5%
if (physicalValue > OUT_MAX) physicalValue = OUT_MAX;
if (physicalValue < OUT_MIN) physicalValue = OUT_MIN;

// Формат для influxdb out:
// msg.payload = [fields, tags]
msg.payload = [
    { value: parseFloat(physicalValue.toFixed(2))}, // поля (fields)
    { sensor: "Flow_H2" } // теги (tags)
];
msg.timestamp = flow.get("cycle_timestamp");
return msg;

